  "full": "整体呈现高质感欧美末日丧尸真人剧风格，强调真实西方演员、电影级摄影与残酷但克制的末世氛围。角色为高辨识度欧美男女，骨相立体、身材修长自然，保留真实毛孔、细小汗毛与皮肤微纹理，肤质干燥哑光、无油光和塑料感。服装以欧美日常穿搭为基础，如夹克、卫衣、牛仔、针织衫和连衣裙，经过轻度灰尘、磨损与撕裂，呈现真实长期生存痕迹，而非夸张废土服装。场景以废弃医院、地下通道、坍塌街区、荒野、公墓、锈蚀桥梁和废弃建筑为主，充满杂乱残骸、风化痕迹与末日环境细节。采用35mm胶片颗粒、Kodak电影色彩、手持摄影、浅景深与变形宽银幕质感。整体冷灰低饱和，搭配自然肤色与少量暗红色环境点缀。以明亮自然光、阴天漫射光和夕阳为主，保持画面清晰通透。丧尸威胁以远处身影、突然出现的异常动静、角色惊恐反应和紧张环境暗示，突出真实生存感、压迫感与心理恐惧，避免血腥特写和过度猎奇。",
