  "full": "本风格详情聚焦于质朴东方式志怪叙事美学，以实体偶动画逐帧拍摄为技术核心，色调锁定低饱和青蓝与赭石，白昼浸染柔和日光与复古赭黄，夜晚则由冷冽月光与微弱灯笼光交织出幽玄氛围，真实胶片颗粒与逐格微抖动赋予影像呼吸感与岁月痕迹。角色造型采用黏土与石膏混合材质，头部饱满宽大，躯干短促呈桶状，丹凤眼、斜飞秀眉、鼻梁挺直、唇色淡朱，瞳孔漆黑无高光，神情清冷肃穆而暗藏叙事张力，模糊性别界限，面部保留自然风干细纹与拇指指纹压痕，杜绝光滑油腻。服饰为明代古风，衣摆布料纹理自然，关节处可见微缩定格支架痕迹。场景纯手工搭建：棉絮云朵、榫卯木片建筑、手绘剥落墙面、仿真苔藓与青石地面，整体拙朴生动，远离电脑渲染，沉入静谧灵异的志怪世界。",
