  "full": "真实中国仙侠电视剧/电影为视觉基准，呈现低饱和度明亮色调与柔和自然光影的统一画面。所有角色均为真人演员，严禁动漫或3D渲染风格。光照遵循物理规律，丝绸服饰呈现自然柔光，皮革腰带与金属盔甲采用真实漫反射材质，仅保留符合现实的克制高光，彻底杜绝油腻反光与虚假光泽。皮肤质感追求全年龄段真实哑光效果，老年人呈现干燥皱纹肌理，儿童保留纯真面部特征，彻底消除油光感与塑料假皮。角色设定涵盖人族、魔族、妖族、仙君四大种族，参考《三生三世十里桃花》美学体系——魔族为东方仙侠人类而非西幻恶魔，仙君神圣典雅不凭空发光。整体色彩统一柔和，景深自然，构建具有真实材质质感的东方仙侠世界观。",
