  "full": "3D 八十年代风格是伴随国内怀旧叙事热潮与 AI 3D 漫剧产业兴起衍生的写实创作赛道，核心是唤醒大众对改革开放初期的集体记忆，且复古质感天然弱化 AI 生成的塑料感，制作适配性极强。风格上采用偏写实的 3D 建模逻辑，色调以暖黄、灰蓝的低饱和复古调为主，自带老胶片朦胧质感；服化道高度还原年代细节，劳动布中山装、碎花布衫、土坯民居、木农具、供销社场景均严谨复刻，人物造型朴实接地气，规避过度美颜，主打真实浓厚的烟火气与生活质感。热门题材集中在赶山打猎逆袭、渔乡水产致富、重生种田创业、年代家庭伦理四大类，核心以 “小人物白手起家逆袭 + 打脸爽点 + 亲情 / 爱情救赎” 为叙事内核，代表作品有《林峰寻妻记》《鱼乡守安宁》《1980 正当年》等。",
