  "full": "AI真人剧该风格是一种追求电影级写实主义的视觉风格。其视觉核心在于将人物与影视摄影美学完美融合，呈现出像素级的“真人”细节：精准复刻人类皮肤自然的微小纹理、毛孔呼吸感以及真实的色彩反馈。畫面採用电影工业标准的打光技法（如体积光、叙事强光），通过自然的景深虚化（Bokeh）与细腻的明暗过渡，勾勒出极具临场感与故事张力的立体空间。色调通常偏向具有电影胶片质感的自然或风格化调色，传递出高规格影视作品特有的沉浸式视听体验。非常适合创作拟真影视剧海报、高质量角色写真、以及需要追求极致摄影质感的视觉内容。",
