  "tool": "gpt_image2",
  "desc": "水果人短剧风格，在上呈现出一种强烈的荒诞感与“恐怖谷”效应交织的独特视觉风格，其核心特征在于将香蕉、草莓、西瓜等日常水果进行高度拟人化处理，赋予它们人类的五官、身材、服饰乃至夸张的肢体动作，使得这些角色既保留了水果本身的色彩与纹理质感，又呈现出人类的情感表达，形成了一种介于真实与虚幻之间的奇特观感",
  "full": "水果人短剧风格，在上呈现出一种强烈的荒诞感与“恐怖谷”效应交织的独特视觉风格，其核心特征在于将香蕉、草莓、西瓜等日常水果进行高度拟人化处理，赋予它们人类的五官、身材、服饰乃至夸张的肢体动作，使得这些角色既保留了水果本身的色彩与纹理质感，又呈现出人类的情感表达，形成了一种介于真实与虚幻之间的奇特观感。在场景与构图方面，这类短剧往往套用传统真人短剧或恋综的成熟模板，将豪华别墅、泳池派对、豪门宴会等极具冲突感的背景与水果主角强行结合，配合高饱和度的色彩与快节奏的剪辑，营造出一种极度夸张、抓马的视觉冲击力。",
