  "desc": "现代都市真人剧风格，本质上是“短剧影像语言 + 韩漫角色审美 ”的融合视觉体系",
  "full": "现代都市真人剧风格，本质上是“短剧影像语言 + 韩漫角色审美 ”的融合视觉体系。画面构建核心是“高颜值、高情绪、高氛围、高精修”。色彩体系通常采用高饱和低灰度的都市电影调色逻辑，通过压暗阴影区域、提升高光纯度与局部霓虹映射来强化视觉冲击。肤色通常处理为冷白皮、奶油肌或轻微蜜桃肤色，通过磨皮与次表面散射模拟实现通透感，皮肤表面会叠加轻微水光高光与柔焦泛光。滤镜与后期是该风格的核心组成部分，通常采用电影级柔光滤镜、Bloom辉光扩散、HDR高动态范围。人物设计属于“半写实偶像化建模逻辑”。角色头身比接近真实人体。女性角色通常采用韩系偶像审美，眼睛会适度放大但不会完全动漫化，重点强化卧蚕、睫毛、眼神高光与湿润感。瞳孔内部会出现玻璃珠般的高光反射。妆容属于高端韩式伪素颜妆体系，底妆极度干净，几乎无瑕疵，通过微光泽肌肤表现高级感。眼妆偏冷调或低饱和灰粉色系，搭配野生眉、淡腮红与韩式咬唇妆，整体强调自然但精致的“女主脸”。男性角色则偏向“韩系男团 + 霸总文学”的结合审美，皮肤通常无明显毛孔与粗糙细节，轮廓清晰，眉眼深邃，带有轻微冷感与禁欲气质。发型多采用蓬松轻碎盖、韩式逗号刘海或层次感纹理短发，通过AI渲染强化发丝丝滑度与高光层次，使头发呈现“偶像剧级别”的顺滑质感。服装设计强调现代都市时尚感与人物身份塑造。打光通常采用电影级三点布光体系，人物面部会保留柔和高光过渡。镜头语言明显模仿竖屏短剧与偶像剧运镜，包括超近景眼神特写、慢动作转头、逆光剪影、雨中对视、车内氛围镜头、天台夜景以及办公室落地窗场景。整体最终呈现出一种“AI生成的高端都市偶像剧视觉”——梦幻、暧昧、轻奢、情绪化，并带有明显“霸总文学视觉化”的戏剧冲击力。",
