  "full": "上海电影美术厂该风格是一种追求东方戏剧美学与赛璐珞手绘极致融合的视觉风格。其视觉核心在于将中国传统戏曲脸谱程式与手工动画工艺完美结合，呈现出极具辨识度的\"舞台银幕\"质感：精准复刻京剧脸谱的线条张力、丹凤眼的程式化勾勒，以及粗黑轮廓线包裹下的高饱和平涂色块。画面采用戏剧舞台标准的打光逻辑（如正面叙事强光、侧影轮廓光），通过零渐变的纯色块碰撞与装饰性民间纹样，构建出极具平面张力与神话叙事能量的东方卷轴式构图空间。色调严格遵循朱砂、石青、藤黄、墨黑的传统矿物颜料体系，传递出1979年经典中国动画学派特有的仪式化、史诗化沉浸式美学体验。非常适合创作神话戏剧角色、历史传奇视觉海报，以及需要追求极致东方风格化艺术质感的视觉内容。",
