  "full": "《K-POP：猎魔女团》风格是索尼标志性,前卫技术与K-Pop工业级视觉美学的完美融合，角色建模采用‘时尚插画级’的夸张九头身理想比例与修长四肢，呈现极具动感张力的几何轮廓与干净利落的哑光质感肤质，妆造完美复刻了当红爱豆的精致与张扬；场景与光影处理大量运用演唱会级别的动态追光、高饱和度的霓虹镭射光束以及浓郁的暗黑都市体积雾，刻意强化戏剧性的高对比度阴影，并在3D空间中大量叠加极具漫画感、法阵与魔法，营造出充满爆发力与音乐律动感的潮酷氛围；材质表现上追求极致的‘视觉提炼’，精准刻画机能战术服的硬朗、全息打歌服的绚丽以及韩国传统萨满元素的神秘，在剥离了物理世界的绝对拟真后，赋予了画面一种前卫的绘本温度；整体以打破次元壁的极致风格化构筑出绚烂、张狂且极具‘动感视听冲击’的都市奇幻舞台，辨识度极高，极其适配都市暗黑神话、音乐驱动型动作场景、潮流虚拟女团以及前卫高燃流行文化类的视觉表达。",
