  "type": "Photorealistic,Fine Art",
  "tool": "gpt_image2",
  "desc": "香港电影风是上世纪八九十年代香港电影黄金时期的经典视觉风格",
  "full": "香港电影风是上世纪八九十年代香港电影黄金时期的经典视觉风格。画面依托于35mm胶片独特的宽容度，呈现出一种高对比度、浓郁饱和且富有颗粒感的影像质感，暗部深邃而富有层次，流淌着一种暧昧的油画底色。场景多取自香港特有的稠密都市空间，层叠的霓虹招牌、狭窄潮湿的后巷与错落的唐楼室内交织，在广角镜头的记录下营造出一种繁华与荒凉并存的迷幻氛围。打光深受黑色电影（Film Noir）与写意主义影响，擅用霓虹灯的红绿蓝补色进行侧向补光，结合迷离的烟雾或雨景，使空间充满了疏离感与宿命论的色彩。色彩方案常以冷峻的青蓝色与灼热的橙红、金黄色形成鲜明撞色，配合演员极具辨识度的浓眉红唇、大波浪发型或利落的风衣衬衫，整体画面如同一场感官丰盛的都市梦境。这种风格在当今社交媒体上作为一种审美标签被广泛推崇，被称为“港风复古感”，它实际上是香港城市文明全盛时期，中西方文化激烈碰撞下所产生的独特美学沉淀。",
