  "full": "《崩坏：星穹铁道》IP风格，是一种精美的三渲二美术风格，其美术呈现出一种融合了科幻与幻想元素的精致二次元风格。笔触上，它注重平滑流畅的线条和精细的角色刻画，并运用柔和的渐变与软阴影代替传统赛璐璐的硬朗色块，营造出细腻的质感。光影处理非常讲究，通过高光和辉光的巧妙运用，赋予画面通透感与华丽感，尤其在角色技能和场景氛围的营造上，光效表现得绚丽夺目。色调方面，整体色彩饱和度高，对比鲜明，但在高饱和的基调下有和谐的色彩搭配。这种风格传递出一种兼具优雅、希望与未来感的积极情绪，同时也带有一丝幻想世界的神秘与浪漫。该风格非常适合描绘异世界冒险、以及将科技与魔法元素相结合的主题。",
