  "desc": "Low Poly风格，采用极简几何切面构建三维形体，以刻意削减的多边形面数塑造物体轮廓，每个三角面均承载独立的平面着色与明确固有色，无平滑过渡、无复杂纹理、无写实材质，强调形体结构与空间体量的可读性，边缘硬朗而色块分明，整体呈现高度抽象的三维风格化质感",
  "full": "Low Poly风格，采用极简几何切面构建三维形体，以刻意削减的多边形面数塑造物体轮廓，每个三角面均承载独立的平面着色与明确固有色，无平滑过渡、无复杂纹理、无写实材质，强调形体结构与空间体量的可读性，边缘硬朗而色块分明，整体呈现高度抽象的三维风格化质感。该风格源于20世纪90年代游戏主机硬件性能受限时期的资产优化需求，后在独立游戏运动与数字艺术浪潮中被重新定义为美学语言，广泛应用于游戏美术、UI插画、建筑体块分析与信息可视化领域，以最低视觉复杂度传达空间体量与材质特征，同时保留高度抽象的几何象征性表达。",
