  "tool": "gpt_image2",
  "desc": "无敌少侠（Invincible）风格是主打美漫成人动画的2D图形化视觉体系，依托经典美式漫画印刷美学与当代数字动画技术融合打造，是融合硬核超级英雄叙事与成人向动画特质的标志性视觉体系",
  "full": "无敌少侠（Invincible）风格是主打美漫成人动画的2D图形化视觉体系，依托经典美式漫画印刷美学与当代数字动画技术融合打造，是融合硬核超级英雄叙事与成人向动画特质的标志性视觉体系。其视觉核心在于平衡漫画图形化表达与动态动画叙事，以高精度2D矢量图形为基底，呈现出动画专属的硬边平面化细节表现：角色采用标准化美漫人体比例与简化面部拓扑结构，搭配绝对平涂的纯色皮肤与服装色块，摒弃任何渐变晕染、体积光过渡或材质纹理细节；线条运用硬边圆笔勾线技术，轮廓粗细统一、转折锋利，关节与衣褶处拒绝任何环境光遮蔽或暗部三角阴影，将人体与服装彻底还原为二维图形色块。背景绘制采用简化的风格化2D动画环境艺术，以平面色域与卡通图形建筑构建空间，拒绝照片级景深、体积雾、大气散射或任何三维写实渲染效果。画面采用高对比度戏剧化平面布光，通过纯粹的明暗色块区分角色与场景，无镜头呼吸、无动态色差、无可控景深，形成绝对二维化的漫画分镜视觉。色调随叙事情绪灵活切换，日常场景偏向明快饱和的动画亮调，战斗与暴力场景多用高对比纯色碰撞与戏剧化剪影，整体色彩摒弃任何写实绘画质感，形成独有的美漫平面化调色体系，传递出残酷激烈、血脉偾张的沉浸式成人动画体验。非常适合创作超级英雄类角色美宣、美漫风格概念原画、动画关键帧、对战主题海报、漫画分镜视觉物料以及硬边平面化动画场景渲染内容。",
