    "text": "《英雄联盟：双城之战》由法国动画工作室 Fortiche Productions 打造的这套视觉体系，是动画史上独树一帜的非描边数字手绘厚涂三渲二视觉范式，它彻底跳脱了传统三渲二的卡通描边桎梏与油画质感的审美惯性，以结构优先的创作逻辑，将硬边型数字手绘厚涂笔触与次世代 PBR 物理渲染体系完成了天衣无缝的融合"
