  "desc": "风格化电影级2D/3D混合数字插画角色设定，核心为极硬数字平刷笔触与强可见笔触结构构成，整体强调 flat brush painting、visible stroke planes、hard-edged unblended color blocks、transparent layered stacking，形成明确的数字板绘风格而非任何渲染或油画质感表现",
  "full": "风格化电影级2D/3D混合数字插画角色设定，核心为极硬数字平刷笔触与强可见笔触结构构成，整体强调 flat brush painting、visible stroke planes、hard-edged unblended color blocks、transparent layered stacking，形成明确的数字板绘风格而非任何渲染或油画质感表现。角色基于依据真实人物比例，非动漫非卡通。脸部为最高视觉优先级（笔触最为夸张明显），face brushwork dominates the entire image，五官完全通过硬挺、清晰、一次性下笔的平面笔触块塑造，不依赖线稿、不依赖轮廓描边、不依赖柔和渐变。脸部必须呈现明显颗粒感与笔触颗粒堆积感（grainy brush texture + visible paint stroke density），强调每一笔不可逆的单次绘制痕迹，使脸部即使在动态视频中也保持强笔触、强颗粒、强平面块结构表现。整体笔触（包含角色以及场景）为 flat digital brush blocks with visible segmentation，大小不一、节奏不均、边缘硬挺清晰，允许轻微随机性但禁止柔化与模糊融合，形成强块面节奏与高可读性绘画结构。整体冷色温基调，保留完整全色域色彩表现，整体饱和度控制在低至中区间，色彩层次丰富细腻，明暗过渡自然，色彩细节饱满。光照为柔和色彩驱动型冷暖过渡，不强调真实物理光影，不产生体积渲染感。皮肤为自然真实肤色（不限制种族），完全哑光，无油光、无塑料感、无反光、无任何油腻或光滑材质表现。服装与环境不设风格限制，仅作为弱化抽象色块存在，不参与设计叙事，不强化材质与装饰。整体视觉必须拒绝油画质感与任何厚涂笔触表现，严格强调数字平刷颗粒感、硬边笔触块、透明叠色结构与强面部笔触可见性。负向词：Q版人物比例、人物写实化、场景真实化、油画质感、油画式涂抹、平滑混色、柔软笔刷、喷枪效果、真实渲染、CGI效果、三维渲染、光泽皮肤、油腻皮肤、塑料皮肤、平滑渐变阴影、柔焦效果、动漫风格、漫画风格、卡通风格、线稿风格、轮廓描边、草图风格、模糊边缘、羽化笔触、霓虹色彩、高饱和度、强烈阴影、死黑阴影、水印、文字、Logo、界面元素。",
