  "full": "超写实游戏CG该风格是一种追求极致物理真实的次世代 3D 美术风格。其视觉核心在于对真实世界人体与物理属性的“微米级”复刻。其标志性特征是其惊人的超级写实皮肤质感： 完美模拟人类皮肤的复杂解剖结构，包括清晰可见的毛孔、细腻的汗毛、细微的皱纹、甚至表皮下的静脉血管纹理，具有真实的次表面散射（SSS）效果，赋予肌肤水润灵动的通透感。在打光上，它彻底遵循现实主义光学规律： 采用复杂的全局光照与丁达尔效应（体积光），让光线在场景中自然漫反射。强烈的叙事性强光与柔和的环境光精准互动，通过极致清晰的明暗过渡，极其自然地勾勒出人物形体，营造出令人屏息的真实临场感与电影级视觉厚重感。非常适合创作对细节要求极高的次世代游戏海报、影视级数字人以及史诗级角色概念设计。",
