  "catLabel": "3D / 欧美 / 游戏",
  "type": "3D,Gaming",
  "tool": "nano",
  "desc": "《赛博朋克2077》（Cyberpunk 2077）的整体视觉体系建立在高度工业化的未来都市审美之上，其角色设计呈现出强烈的“功能性赛博义体 + 时尚化人体结构”的混合特征：面部五官普遍强调锐利轮廓与高对比结构，皮肤质感介于真实人类与合成材料之间，常见毛孔细节、金属植入接口、机械关节缝隙与发光义体模块并存，形成“生物与机械共生”的视觉语言",
  "full": "《赛博朋克2077》（Cyberpunk 2077）的整体视觉体系建立在高度工业化的未来都市审美之上，其角色设计呈现出强烈的“功能性赛博义体 + 时尚化人体结构”的混合特征：面部五官普遍强调锐利轮廓与高对比结构，皮肤质感介于真实人类与合成材料之间，常见毛孔细节、金属植入接口、机械关节缝隙与发光义体模块并存，形成“生物与机械共生”的视觉语言；服装设计融合街头潮流、高端科技品牌与战术功能性结构，大量采用PVC、金属涂层织物、碳纤维质感材料与霓虹发光嵌条，整体剪影夸张且富有攻击性，强调个体身份标签与阶层差异的视觉外显。在画面滤镜与渲染风格上，整体采用高对比HDR光照体系与电影级色彩分级（color grading），通过强烈的明暗分割、局部过曝霓虹光源、以及体积雾与镜面反射强化“夜之城”的沉浸压迫感，同时配合轻微胶片颗粒与镜头畸变效果，使画面兼具写实摄影感与超现实未来感的张力。色彩表现上以大地色系作为基础底盘，大量使用深蓝、墨紫、青绿色阴影构建城市基调，同时以高饱和霓虹色（电蓝、品红、荧光黄、酸性绿）作为局部视觉爆点，通过色彩对冲强化信息密度与视觉冲击，形成典型的“暗底霓虹爆破式色域结构”。场景构建方面则体现出极端密集的垂直城市结构与多层空间叠加逻辑，高楼群体呈现出压缩式空间透视与夸张尺度对比，街道充斥动态广告屏、全息投影、拥挤交通与功能性管线结构，形成强烈的“空间信息饱和”效果；环境细节覆盖范围极广，从贫民窟的破败金属结构到企业区的极简玻璃幕墙与冷光建筑，均通过材质差异与光源分层构建出清晰的阶级空间分区，使整个世界既具备高度真实的城市逻辑。",
