  "desc": "福克斯小镇是一种专为海外网络短剧和甜宠、奇幻题材定制的真人视觉风格",
  "full": "福克斯小镇是一种专为海外网络短剧和甜宠、奇幻题材定制的真人视觉风格。其视觉核心在于营造自带‘网络流媒体滤镜’的梦幻与宿命感：画面彻底告别了生硬、高反差的工业电影打光，转而采用低对比度、高光溢出（Bloom Effect）以及细腻的空气扩散散光，让光影在演员面部和边缘勾勒出毛茸茸的唯美轮廓（Rim Lighting）。\n画面自带一种微妙的柔焦（Soft-focus）与奶油般丝滑的景深虚化（Creamy Bokeh），既保留了真人演员自然的皮肤肌理与情绪微表情，又抹去了数字摄影机过于凌厉的死板线条，呈現出一种自带水汽与迷雾感的‘故事氛围’。色调上多采用低饱和、高容错的唯美网络调色盘，极具流媒体霸总、狼人剧的吸睛质感。非常适合创作海外短剧分镜、竖屏推流海报、情感类短剧角色写真，以及需要追求浪漫、治愈或神秘朦胧张力的视觉内容。",
