  "desc": "Rockstar Games标志性\"电影级写实渲染\"前沿技术与美国边疆工业级视觉美学的完美融合，角色建模采用\"真人扫描级\"的写实人体比例与饱经风霜的面部肌理，呈现极具力量张力的西部轮廓与阳光侵蚀般的粗糙哑光肤质，妆造完美复刻了1899年亡命之徒的粗犷与时代终结的悲壮",
  "full": "Rockstar Games标志性\"电影级写实渲染\"前沿技术与美国边疆工业级视觉美学的完美融合，角色建模采用\"真人扫描级\"的写实人体比例与饱经风霜的面部肌理，呈现极具力量张力的西部轮廓与阳光侵蚀般的粗糙哑光肤质，妆造完美复刻了1899年亡命之徒的粗犷与时代终结的悲壮；场景与光影处理大量运用电影摄影级别的动态追光、高饱和度的黄金时段光束以及浓郁的Frontier Dust体积雾，刻意强化戏剧性的高对比度明暗对比，并在3D空间中大量叠加极具胶片质感的\"电影颗粒与变形耀斑（Film Grain & Anamorphic Flares）\"来勾勒枪火、马蹄扬尘与风暴，营造出充满爆发力与西部律动感的苍凉氛围；材质表现上追求极致的\"物理拟真\"，精准刻画风化皮革的龟裂纹路、牛仔布的粗粝经纬以及左轮金属的冷峻磨损，在剥离了卡通世界的夸张变形后，赋予了画面一种前卫的电影胶片温度；整体以打破游戏与电影界限的极致写实构筑出苍茫、悲壮且极具\"旧西部史诗冲击\"的边疆舞台，辨识度极高，极其适配美国边疆神话、暴力驱动的生存 Drama、写实西部群像以及前卫电影化叙事类的视觉表达。",
