  "full": "都市言情该风格是极具辨识度的现代都市言情漫画风格。其视觉核心在于精致写实的人物造型与时尚化的形象塑造（如修身礼服、奢华配饰、细腻妆容）。笔触由流畅细腻的线条构成，注重人体比例的美感呈现（如修长身形、精致五官），同时通过发丝、衣料褶皱的细节刻画增强质感。光影处理上，采用柔和的渐变渲染技法，通过明暗过渡塑造人物的立体感与氛围层次（如皮肤的光泽、布料的垂坠感），并结合场景的暖调光斑营造都市夜景的浪漫氛围。色调上，偏好高质感的莫兰迪色系或浓郁都市色调（如酒红、雅黑），搭配金属 / 宝石的璀璨光泽，传递精致、优雅的都市气质。非常适合创作都市恋爱漫画、豪门言情绘本、时尚女性向视觉作品，或是需要传递精致、深情且具有都市氛围感的情感类内容",
