  "full": "辛普森风格是极具辨识度的经典美式成人动画风格。其视觉核心在于极简的几何化造型与标志性的黄色皮肤。笔触由粗细均匀的黑色轮廓线构成，线条圆润流畅，刻意忽略了解剖学的严谨性（如圆柱状的四肢、特异的嘴部咬合结构）。光影处理上，它完全采用二维平涂技法（Flat Shading），不仅没有复杂的体积光影，甚至摒弃了大部分阴影细节，追求绝对的平面感。色调上，采用明快、鲜艳且高对比度的纯色块填充。这种风格充满讽刺幽默与市井生活气息。非常适合创作社会讽刺漫画、情景喜剧类绘本、个性化且带有波普意味的头像设计，或是需要传递轻松、荒诞且具有大众亲和力的视觉宣传品。",
