  "full": "恐怖悬疑该风格是恐怖悬疑漫画风格。其笔触通过粗重、有力的黑色线条勾勒轮廓，并以大面积的阴影和深邃的黑色色块填充，形成强烈的明暗对比和高反差的视觉效果，强调紧张和压抑的气氛。它运用简洁而精准的线条来描绘细节（如人物的五官、制服褶皱、桌面上的物品），并使用刮擦或点状的纹理来表现环境的破败、粗糙和颗粒感。色调以低饱和度的青灰色、黑色和白色为主，营造出冰冷、压抑、恐怖的氛围，在人物的眼睛等局部会用高饱和度的红色进行点缀，以突出惊恐、血腥或疯狂的情绪。这种风格传递出一种惊悚、不安、黑暗且充满暴力暗示的情绪。适合的内容主题是悬疑惊悚故事、恐怖/犯罪题材的漫画分镜、末日废土题材的插画或紧张压抑的场景概念艺术。",
