  "full": "名侦探阿楠该IP风格是经典推理动漫IP《名侦探柯南》风格，其最显著的特征在于清晰锐利的黑色线条笔触，人物轮廓和场景结构都勾勒得非常明确，尤其是在描绘人物，特别是眼睛和发型时，具有极高的辨识度。光影处理上对比强烈，常利用大面积的阴影和高光来制造悬疑和紧张感，尤其是在表现罪犯或揭示线索的关键时刻，光影的戏剧化运用是其标志。色调方面，日常场景色彩明亮饱和，但在进入案件或推理环节时，色调会转向深沉、偏冷的蓝色或灰色调，以渲染神秘甚至略带一丝恐惧的情绪。这种风格传递出的核心情绪是紧张、悬疑与理智并存，在日常的轻松愉快与案件的严肃凝重之间切换。非常适合描绘现代都市背景下的侦探推理故事、悬疑解谜情节、角色之间充满张力的对峙场景，以及需要通过环境和细节来铺陈线索的叙事性插画。",
