  "desc": "可爱马卡龙该风格的核心特征在于其随性而粗糙的笔触，线条带有类似蜡笔或铅笔的颗粒质感，显得轻松活泼",
  "full": "可爱马卡龙该风格的核心特征在于其随性而粗糙的笔触，线条带有类似蜡笔或铅笔的颗粒质感，显得轻松活泼。光影方面处理得极为简化，基本采用平涂和硬朗的色块来表现阴影，不追求立体感，强调扁平化的装饰性。色调以低饱和度的粉彩和马卡龙色系为主，即使出现深色背景，整体氛围也因明快的色彩搭配而显得清新、甜美。这种画风传递出的情绪是可爱、诙谐且富有戏剧性的，通过Q版的人物比例和夸张的表情来营造一种轻松有趣的氛围。因此，该风格非常适合用于创作角色头像、社交媒体表情包、趣味短漫、手账素材或可爱的周边产品（如亚克力立牌、钥匙扣），也同样适用于描绘童话故事书或任何以展现角色萌感为主要目的的插画内容。",
