  "desc": "哥特都市涂鸦该风格是patzzi画师风格，在技法上融合了略带杂乱感的铅笔质感线稿与平滑的色块，并辅以柔和的渐变进行阴影和高光的处理，同时叠加了细微的杂色与颗粒纹理，营造出一种精致的粗糙感",
  "full": "哥特都市涂鸦该风格是patzzi画师风格，在技法上融合了略带杂乱感的铅笔质感线稿与平滑的色块，并辅以柔和的渐变进行阴影和高光的处理，同时叠加了细微的杂色与颗粒纹理，营造出一种精致的粗糙感。其笔触表现为不拘小节的随性线条，与大面积的柔和色块形成对比。光影处理偏向于柔和的漫射光，缺乏强烈的明暗对比，使得整体画面笼罩在一种朦胧的氛围中。色调采用低饱和度的灰色调和莫兰迪色系，点缀以柔和的亮色，整体色彩清冷而统一。这种风格传递出一种时尚、平和、有趣、可爱的情绪，非常适合描绘街头时尚、同人创作、日常、动漫、冒险故事。",
