  "desc": "光栅像素艺术该风格是tomoruka mr画师风格，技法上属于精细的像素艺术（Pixel Art），但通过高分辨率和丰富的色彩层次，规避了传统低像素的粗糙感，实现了类似现代数字绘画的平滑轮廓与细腻过渡",
  "full": "光栅像素艺术该风格是tomoruka mr画师风格，技法上属于精细的像素艺术（Pixel Art），但通过高分辨率和丰富的色彩层次，规避了传统低像素的粗糙感，实现了类似现代数字绘画的平滑轮廓与细腻过渡。笔触精准而干净。光影处理明快通透，常设定一个柔和的主光源，产生清晰分明的亮部与暗部，但阴影内部的色彩变化依然丰富，营造出空气感和立体感。色调清新、饱和度偏高，充满活力的色彩，整体呈现出一种日系动画般的明亮氛围。这种风格传递出一种怀旧、宁静而又略带梦幻的积极情绪，非常适合描绘梦核、复古、怀旧、现代都市生活、青春故事、角色肖像以及带有幻想色彩的风景，能赋予画面一种介于复古游戏与当代插画之间的独特美感。",
