  "desc": "欧漫概念艺术该画风呈现出非常强烈的欧洲漫画（Bande Dessinée）和硬核游戏概念艺术的融合风格，让人联想到艺术家如Mike Mignola或Kim Jung Gi的笔法",
  "full": "欧漫概念艺术该画风呈现出非常强烈的欧洲漫画（Bande Dessinée）和硬核游戏概念艺术的融合风格，让人联想到艺术家如Mike Mignola或Kim Jung Gi的笔法。线条粗犷、果断且充满力量感，运用了大量的黑色块和硬朗的交叉影线（hatching）来塑造形态与阴影。在光影处理上，风格极为大胆且充满戏剧性，通过高对比度的明暗关系来强调物体的体积感和画面的纵深。色调饱和度不高，常以大面积的冷色或中性色为基调，再用小范围的亮色或对比色进行点缀。这种画风传递出的情绪是严肃、深沉、坚毅与孤独感。这个画风适合描绘如黑暗奇幻、废土科幻、史诗战争或侦探故事等具有厚重世界观和成人化主题的内容，尤其适用于制作风格独特的漫画、游戏设定集、插画小说封面，以及展现复杂机械结构或生物质感的高端手办（figurine）的概念设计。",
