  "full": "东方淡彩此风格融合了东方古典美学与现代二次元插画的精致风格，近似于当下流行的“国风”或高品质游戏美术。其笔触极为细腻干净，线条流畅，色彩渲染上多采用平滑柔和的过渡，几乎没有粗犷的笔刷痕迹，整体呈现出数字绘画的精致与平滑感。在光影方面，该风格偏好使用柔和、均匀的漫射光，营造出一种宁静、朦胧且略带梦幻的氛围，光影关系微妙而富有空气感。色调以低饱和度的暖色系和马卡龙色系为主，如米白、淡粉、浅青等，观感温润、雅致且和谐。这种视觉语言共同传递出一种静谧、温柔、纯净，时而带有一丝淡淡忧郁的复杂情绪。因此，该风格非常适合描绘东方幻想故事、宫廷贵族少女、带有神话色彩的人物、或温馨治愈的童话绘本等主题，能够细腻地刻画角色的情感世界和空灵的故事氛围。",
