  "full": "文艺复兴古典画是对15-16世纪欧洲文艺复兴时期古典肖像画风格的完美复刻。其笔触极为细腻、平滑，通过油画罩染技术达到的效果，对皮肤、织物的质感刻画入微。光影处理是典型的“明暗对照法”（Chiaroscuro），柔和的侧光塑造出人物强烈的立体感和真实感。色调丰富、沉稳，以华贵的绿色和金色为主，充满了古典韵味。画面情绪庄重、宁静，带有一种超越时间的、谜一般的典雅气质。这种风格极度适合描绘历史题材、中世纪贵族肖像、宗教故事以及用于博物馆级的艺术创作和影视概念设计。",
