  "full": "柔和光影厚涂卡通该风格是malberrybush画师风格，流畅精准的线条与柔和细腻的色彩渲染相结合。运用类似数字喷枪或柔边笔刷的工具，创造出平滑的色彩过渡和柔和的阴影。光影采用温暖的、带有些许辉光的侧光源，使人物和景物笼罩在柔光之中。色调鲜明且饱和度高，色彩搭配和谐。整体上传递出一种温暖、治愈、梦幻且略带一丝怀旧的情绪。这种风格非常适合用于描绘情感细腻的角色肖像、动漫或游戏同人创作、视觉小说立绘以及富有故事感的都市生活或幻想场景。",
