  "tool": "novelai",
  "desc": "棱镜故障艺术该风格是iro画师风格，巧妙融合了清晰锐利的日系动漫线条与数字化的像素及故障艺术（Glitch Art）元素，角色主体轮廓分明，而背景和光效中则融入了明显的像素格与抖动纹理，营造出一种数字屏幕般的独特质感",
  "full": "棱镜故障艺术该风格是iro画师风格，巧妙融合了清晰锐利的日系动漫线条与数字化的像素及故障艺术（Glitch Art）元素，角色主体轮廓分明，而背景和光效中则融入了明显的像素格与抖动纹理，营造出一种数字屏幕般的独特质感。渲染方式使用平滑的色彩渐变和类似半色调（Halftone）的网点图案来塑造形体与材质。光影处理运用了大量明亮的环境光和多彩的边缘光，使画面呈现出一种通透、发光的视觉效果，阴影部分也充满了丰富的色彩。色调上，作品偏爱使用青色、粉色、紫色等高饱和度的霓虹色系，整体散发出一种充满活力、如梦似幻的未来感氛围。这种风格传递出乐观、梦幻且充满动感的青春情绪，极其适合描绘迷幻美学、赛博朋克角色、数字虚拟偶像、现代游戏动漫的同人创作。",
