  "full": "极简色块复古波普该风格是4qw5画师风格，一种融合了动漫美学与平面设计感的极简艺术。完全舍弃了传统的轮廓线，转而使用大块、边缘锐利的纯色块来构建形态与结构，形成一种类似色谱版画或海报的视觉效果。光影处理极为简化，通过几何形状的平涂色块来区分明暗。色调倾向于使用有限且饱和度较低的色彩组合，营造出一种和谐、克制且略带复古的氛围。这种冷静、疏离的视觉语言传递出一种平静、沉闷甚至带有一丝孤独和忧伤的情绪。非常适合表现科幻、赛博背景下的城市生活，或聚焦于人物孤独内心与记忆片段的青春故事主题。",
